// Run: node day36/debug/report.js
const orders = [
  { id: 1, customer: 'Asha', amount: 250, status: 'delivered' },
  { id: 2, customer: 'Ravi', amount: 1200, status: 'cancelled' },
  { id: 3, customer: 'Asha', amount: 75, status: 'delivered' },
  { id: 4, customer: 'Meena', amount: 980, status: 'delivered' },
  { id: 5, customer: 'Ravi', amount: 300, status: 'delivered' },
];

// 1. Revenue from delivered orders (expect 1605)
const delivered = orders.filter((o) => { o.status === 'delivered' });
const revenue = delivered.reduce((sum, o) => sum + o.amount);

// 2. All amounts, high to low (expect [1200, 980, 300, 250, 75])
const sorted = orders.map((o) => o.amount).sort();

// 3. Delivered spend per customer (expect { Asha: 325, Meena: 980, Ravi: 300 })
const perCustomer = {};
for (const o of delivered) {
  perCustomer[o.customer] = perCustomer[o.customer] + o.amount;
}

// 4. 10% discount on every order, without changing the originals
const discounted = orders.map((o) => { o.amount = o.amount * 0.9; return o; });

console.log('revenue', revenue);
console.log('sorted', sorted);
console.log('perCustomer', perCustomer);
console.log('discounted first', discounted[0].amount); // expect 225
console.log('original first', orders[0].amount);      // expect 250
